// The gallery uses a compressed longitudinal scale to fit the visitable hall.
function mountBase(g,x,z,length,width) {
  g.box([x,.09,z],[length,.18,width],'#594f46');
  g.box([x,.20,z],[length-.07,.04,width-.07],'#c6b9a2');
}

function quadrupedLegs(m,hip,shoulder,width,heavy) {
  for(const s of [-1,1]){
    m.pelvis(hip,s,width*.74);
    for(const [joint,front] of [[hip,false],[shoulder,true]]){
      const root=fossilOffset(joint,front?.04:0,-.38,s*width*.74);
      if(front) m.scapula(fossilOffset(root,-.95,.74,-.04*s),root,s,heavy*1.48);
      const knee=[root[0]+(front?-.18:.26)+s*.15,root[1]*.51,s*(width*.85)];
      const ankle=[root[0]+(front?.15:-.17)+s*.27,.36,s*width*.86];
      const foot=fossilOffset(ankle,.075,-.23,0);
      m.bone(root,knee,heavy); m.bone(knee,ankle,heavy*.77);
      m.bone(fossilOffset(knee,-.13,0,s*.10),fossilOffset(ankle,-.10,0,s*.09),heavy*.36);
      if(heavy>.2&&front){
        // Sauropod forefeet bear weight on a crescent of vertical metacarpals.
        for(let i=-2;i<=2;i++){
          const a=i*.65;
          m.bone(fossilOffset(ankle,.042*Math.cos(a),0,.07*Math.sin(a)),
                 fossilOffset(foot,.14*Math.cos(a),0,.16*Math.sin(a)),heavy*.29);
        }
      }else m.pes(ankle,foot,s,heavy*4.7);
    }
  }
}

function addTitan(g) {
  mountBase(g,-.1,0,21.9,3.6);
  if(typeof collectionHasObject==='function' && collectionHasObject('titan')) return;
  const m=fossilSkeleton(g,[0,.22,0],1,1,['#a16e50','#ab7757','#966747','#ae7e60','#ae7655','#8d614b']);
  const hip=[-2.4,3.63,0],shoulder=[1.56,4.02,0],skull=[9.22,4.5,-.38];
  m.spine([hip,[-4.68,3.1,.09],[-6.98,2.35,.3],[-8.75,1.98,.76],[-10.78,1.8,1.12]],38,.29,.036,1.95,true);
  m.spine([hip,[-.92,3.94,0],shoulder],16,.32,.26,2.3);
  m.ribs(hip,shoulder,15,1.88,1.23);
  m.spine([shoulder,[3.71,4.11,-.05],[6.18,4.22,-.22],[7.73,4.53,-.3],skull],20,.249,.092,1.35,false,'cervical');
  m.head(skull,.66,false);
  quadrupedLegs(m,hip,shoulder,1.13,.237);
  m.rod([-2.4,0,0],hip,.039,.039,'#4c4942');
  m.rod([1.56,0,0],shoulder,.039,.039,'#4c4942');
}

// The educator plan places ceratopsians in the western half, armored
// dinosaurs in the eastern half, and the hadrosaurs along the opposite wall.
const ornithLayout={trike:[-4.68,4.02],stego:[7.56,4.22]};
function ornithMountCentre(kind){
  const r=catalog.get('ornith'),[x,z]=ornithLayout[kind];return [x*r.sx/r.sy,z*r.sz/r.sy];
}
function addOrnith(g) {
  const [tx,tz]=ornithMountCentre('trike'),[sx,sz]=ornithMountCentre('stego');
  mountBase(g,tx,tz,10.2,2.94);
  mountBase(g,sx,sz,10.2,2.94);
  const trike=fossilSkeleton(g,[tx,.22,tz],1,1,['#674d3b','#6c533e','#75583f','#715641','#574638']);
  const hip=[-1.14,2.43,0],shoulder=[.98,2.14,0];
  trike.spine([hip,[-2.15,1.95,.05],[-3.28,1.45,.26],[-4.59,1.15,.32]],22,.17,.04,1.8,true);
  trike.spine([hip,[-.18,2.49,0],shoulder],12,.21,.16,2.1);
  trike.ribs(hip,shoulder,12,1.18,.75);
  trike.spine([shoulder,[1.39,2.05,0],[1.81,1.99,0]],5,.17,.14,1.45);
  quadrupedLegs(trike,hip,shoulder,.77,.162);

  // Use the comparative Smithsonian skull when the AMNH gallery scan is unavailable.
  if(typeof collectionHasObject!=='function' || !collectionHasObject('trike'))
    fossilScannedMesh(g,triceratopsSkull,[tx+1.76,2.35,tz],.99);

  const stego=fossilSkeleton(g,[sx,.22,sz],1,-1,['#815e44','#7b5d48','#86684d','#745640','#816247']);
  const H=[-.9,2.6,0],S=[1.23,1.78,0],head=[2.7,1.16,0];
  const axis=[[-4.8,1.54,.55],[-3.52,1.68,.3],[-2.38,2.07,.16],H,[.18,2.51,0],S,[1.96,1.39,0],head];
  stego.spine([H,axis[2],axis[1],axis[0]],24,.17,.042,1.5,true);
  stego.spine([H,axis[4],S],12,.208,.145,1.9);
  stego.spine([S,axis[6],head],7,.145,.076,1.35);
  stego.ribs(H,S,12,1.32,.85); stego.head(head,.46,false);
  quadrupedLegs(stego,H,S,.75,.143);
  // Alternating osteoderms have a thick basal ridge and thin blade edges.
  for(let i=0;i<17;i++){
    const t=.20+i*.045, p=stego.position(axis,t), side=i%2?1:-1;
    const h=.20+1.10*Math.pow(Math.sin(Math.PI*i/16),.9), w=h*.43;
    const at=(x,y,z)=>fossilOffset(p,x,y,side*(.14+z));
    const ring=[at(-w*.45,.1,0),at(-w*.86,h*.64,.12),at(-w*.27,h,.15),at(w*.64,h*.80,.14),at(w*.78,h*.34,.07),at(w*.31,.10,0)];
    for(let j=0;j<ring.length;j++){
      stego.plate(ring[j],ring[(j+1)%ring.length],at(-.01,h*.45,.19));
    }
    stego.rod(at(0,.12,0),at(-.03,h*.79,.14),.04,.012);
  }
  for(const [x,y,z] of [[-4.25,1.57,.44],[-3.92,1.61,.38]]){
    for(const side of [-1,1]) stego.rod([x,y,z], [x-.33,y+.40,z+side*.70],.11,.009);
  }
}

// Comparative Triceratops skull, Smithsonian USNM PAL 500000. Public domain.
// https://sketchfab.com/3d-models/e9c507f179ed4455aac3b208c9e6c973
// Isolated cranium and mandible, reoriented, decimated and colour-baked.
const triceratopsSkull={"lo":[-0.48721,-0.843315,-0.7731],"span":[2.1766,1.646119,1.5971],"p":"","c":"","n":"","i":""};

function apatosaurusMount(){
  const g=new GalleryMesh();
  const m=fossilSkeleton(g,[0,.24,0],1,1,['#675647','#796452','#655243','#806a57','#6e5744'],'diplodocid');
  const hip=[-1.65,3.46,0],shoulder=[1.15,3.29,0],skull=[7.65,4.20,.24];
  m.spine([hip,[-3.78,3.09,.12],[-6.85,2.67,.36],[-9.45,2.22,.76],[-12.0,2.51,1.08]],44,.282,.025,1.68,true);
  m.spine([hip,[-.45,3.68,0],shoulder],14,.31,.26,2.18);
  m.ribs(hip,shoulder,15,1.47,.99);
  m.spine([shoulder,[2.75,3.46,0],[4.74,3.74,.07],[6.44,4.12,.15],skull],17,.268,.092,1.32,false,'cervical');
  m.head(skull,.56,false);quadrupedLegs(m,hip,shoulder,.97,.247);
  for(const joint of [hip,shoulder])m.rod([joint[0],0,0],joint,.034,.034,'#47413c');
  const mesh=g.finish(true);mesh.rotation.y=-Math.PI/2;return mesh;
}
